<?php
require __DIR__.'/app/bootstrap.php';require __DIR__.'/app/growth_public.php';if(!growth_enabled('emergency_portal_enabled',true)){http_response_code(404);exit('Emergency portal disabled.');}
$city=(int)($_GET['city_id']??0);$items=growth_emergency_services($city?:null,100);$cities=growth_rows("SELECT id,name FROM cities WHERE status=1 ORDER BY name");
growth_public_head('Emergency & Public Services','Emergency numbers, hospitals, rescue, police and useful public services.','emergency');
?>
<section class="growth-hero"><div class="lt-shell growth-hero-grid"><div><span>EMERGENCY & CITY HELP</span><h1>Useful numbers when you need them most.</h1><p>Find rescue, hospitals, police, pharmacies and public-service contacts from the ShahkotPK city directory.</p></div><aside class="growth-hero-panel"><b><?=e(count($items))?></b><small>Active public-service contacts</small></aside></div></section>
<section class="growth-section"><div class="lt-shell"><div class="growth-section-head"><div><span>PUBLIC SERVICES</span><h2>Emergency & Useful Contacts</h2></div><form method="get"><select class="growth-input" name="city_id" onchange="this.form.submit()"><option value="">All Cities</option><?php foreach($cities as $c):?><option value="<?=e($c['id'])?>" <?=$city==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></form></div><div class="growth-card-grid"><?php foreach($items as $x):?><article class="growth-card"><div class="growth-card-body"><span><?=e(strtoupper($x['service_type']))?> · <?=e($x['city_name'])?></span><h3><?=e($x['name'])?></h3><p><?=e($x['address'])?></p><?php if($x['is_24_7']):?><b class="growth-badge">24/7</b><?php endif;?><div class="growth-actions"><?php if($x['phone']):?><a href="tel:<?=e($x['phone'])?>">Call <?=e($x['phone'])?></a><?php endif;?><?php if($x['map_url']):?><a target="_blank" href="<?=e($x['map_url'])?>">Directions</a><?php endif;?></div></div></article><?php endforeach;?></div><?php if(!$items):?><div class="growth-empty">No emergency/public service contacts have been published for this filter yet.</div><?php endif;?></div></section>
<?php growth_public_footer(); ?>
